use crate::config::Config;
use crate::focus::FocusContext;
use crate::upload::{rotate_and_upload, UploadConfig};
use chrono::Utc;
use log::{debug, info, warn};
use serde::{Deserialize, Serialize};
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::thread;

static ROTATION_IN_PROGRESS: AtomicBool = AtomicBool::new(false);
static WRITES_SINCE_CHECK: AtomicUsize = AtomicUsize::new(0);
const WRITES_PER_SIZE_CHECK: usize = 50;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogEntry {
    pub timestamp: chrono::DateTime<chrono::Utc>,
    pub key: Key,
    pub focus: Option<FocusContext>,
    pub duration_ms: u64,
    #[serde(rename = "type")]
    pub entry_type: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Key {
    pub device_id: u32,
    pub key_code: u8,
    pub key_name: Option<String>,
    pub is_pressed: bool,
    pub character: Option<char>,
    pub modifiers: Vec<u8>,
}

pub fn create_log_file_from_config(config: &Config) -> Result<String, String> {
    let timestamp = Utc::now().format("%Y-%m-%d_%H-%M-%S").to_string();
    let log_dir = &config.log_dir;

    fs::create_dir_all(log_dir)
        .map_err(|e| format!("Failed to create logs directory '{}': {}", log_dir, e))?;

    let log_file = format!("{}/{}.log", log_dir, timestamp);
    info!("Log directory: {}", log_dir);

    Ok(log_file)
}

pub(crate) fn write_to_log(log_file: &str, entry: &LogEntry) -> Result<(), String> {
    // Ensure parent directory exists (handles external deletion of logs dir)
    if let Some(parent) = std::path::Path::new(log_file).parent() {
        if !parent.exists() {
            fs::create_dir_all(parent)
                .map_err(|e| format!("Failed to recreate log directory: {}", e))?;
        }
    }

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_file)
        .map_err(|e| format!("Failed to open log file: {}", e))?;

    let json = serde_json::to_string_pretty(entry)
        .map_err(|e| format!("Failed to serialize entry: {}", e))?;

    file.write_all(json.as_bytes())
        .map_err(|e| format!("Failed to write to log: {}", e))?;
    file.write_all(b"\n")
        .map_err(|e| format!("Failed to write newline: {}", e))?;

    debug!("Entry written: {:?}", entry.key);
    Ok(())
}

pub fn write_to_log_with_rotation_check(
    log_file: &str,
    entry: &LogEntry,
    upload_config: &UploadConfig,
) -> Result<(), String> {
    write_to_log(log_file, entry)?;

    let count = WRITES_SINCE_CHECK.fetch_add(1, Ordering::Relaxed) + 1;
    if count >= WRITES_PER_SIZE_CHECK {
        WRITES_SINCE_CHECK.store(0, Ordering::Relaxed);
        let _ = check_and_rotate_log(log_file, upload_config);
    }

    Ok(())
}

impl LogEntry {
    pub fn new(
        timestamp: chrono::DateTime<chrono::Utc>,
        key: Key,
        focus: Option<FocusContext>,
    ) -> Self {
        Self {
            timestamp,
            key,
            focus,
            duration_ms: 0,
            entry_type: "key".to_string(),
        }
    }
}

pub fn format_entry_summary(entry: &LogEntry) -> String {
    let key = &entry.key;
    let state = if key.is_pressed { "down" } else { "up  " };
    let primary = key
        .character
        .map(|ch| format!("'{}'", ch))
        .or_else(|| key.key_name.clone())
        .unwrap_or_else(|| format!("code:{}", key.key_code));

    let modifiers = format_modifier_summary(&key.modifiers);
    let focus = format_focus_summary(entry.focus.as_ref());
    format!(
        "[{}] {:<12} key_code={} mods={}{}",
        state, primary, key.key_code, modifiers, focus
    )
}

fn format_modifier_summary(modifiers: &[u8]) -> String {
    if modifiers.is_empty() {
        return "[]".to_string();
    }

    let names: Vec<String> = modifiers
        .iter()
        .map(|modifier| modifier_name(*modifier).unwrap_or("unknown").to_string())
        .collect();

    format!("[{}]", names.join("+"))
}

fn modifier_name(key_code: u8) -> Option<&'static str> {
    match key_code {
        0x37 => Some("cmd"),
        0x38 => Some("shift"),
        0x39 => Some("caps"),
        0x3a => Some("opt"),
        0x3b => Some("ctrl"),
        0x3f => Some("fn"),
        _ => None,
    }
}

fn format_focus_summary(focus: Option<&FocusContext>) -> String {
    let Some(focus) = focus else {
        return String::new();
    };

    let app = focus.app_name.as_deref().unwrap_or("unknown-app");
    let title = focus.window_title.as_deref().unwrap_or("unknown-window");
    format!(" app={} window={}", app, title)
}

pub fn get_log_file_size(log_file: &str) -> Result<u64, String> {
    let metadata =
        fs::metadata(log_file).map_err(|e| format!("Failed to get log file metadata: {}", e))?;
    Ok(metadata.len())
}

pub fn check_and_rotate_log(log_file: &str, upload_config: &UploadConfig) -> Result<(), String> {
    if !upload_config.upload_enabled {
        return Ok(());
    }

    if ROTATION_IN_PROGRESS.load(Ordering::Relaxed) {
        return Ok(());
    }

    let size = match get_log_file_size(log_file) {
        Ok(size) => size,
        Err(_) => {
            // File was deleted externally — next write will recreate it
            return Ok(());
        }
    };

    if size < upload_config.upload_threshold_bytes as u64 {
        return Ok(());
    }

    info!(
        "Log file size {} bytes exceeds threshold {} bytes, rotating",
        size, upload_config.upload_threshold_bytes
    );

    ROTATION_IN_PROGRESS.store(true, Ordering::Relaxed);

    let log_file_owned = log_file.to_string();
    let endpoint = if upload_config.upload_endpoint.is_empty() {
        String::new()
    } else {
        upload_config.upload_endpoint.clone()
    };
    let max_retries = upload_config.upload_max_retries;

    thread::spawn(move || {
        match rotate_and_upload(&log_file_owned, &endpoint, max_retries) {
            Ok(_) => info!("Log rotation completed"),
            Err(e) => warn!("Log rotation failed: {}", e),
        }
        ROTATION_IN_PROGRESS.store(false, Ordering::Relaxed);
    });

    Ok(())
}

#[cfg(test)]
mod tests {
    use crate::focus::FocusContext;
    use crate::upload::UploadConfig;

    use super::{
        format_entry_summary, write_to_log, write_to_log_with_rotation_check, Key, LogEntry,
    };

    fn test_entry() -> LogEntry {
        LogEntry::new(
            chrono::Utc::now(),
            Key {
                device_id: 0,
                key_code: 8,
                key_name: Some("c".to_string()),
                is_pressed: true,
                character: Some('C'),
                modifiers: vec![0x38, 0x3b],
            },
            Some(FocusContext {
                app_name: Some("Ghostty".to_string()),
                app_pid: Some(123),
                window_title: Some("Shell".to_string()),
                window_role: None,
                window_subrole: None,
            }),
        )
    }

    #[test]
    fn formats_character_and_modifiers_in_live_view() {
        let summary = format_entry_summary(&test_entry());
        assert!(summary.contains("[down]"));
        assert!(summary.contains("'C'"));
        assert!(summary.contains("mods=[shift+ctrl]"));
        assert!(summary.contains("app=Ghostty"));
        assert!(summary.contains("window=Shell"));
    }

    #[test]
    fn recreates_log_file_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_delete");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        let config = UploadConfig {
            upload_enabled: false,
            ..Default::default()
        };

        // Write an entry — file is created
        write_to_log_with_rotation_check(path_str, &test_entry(), &config).unwrap();
        assert!(log_path.exists());
        let size_after_first = std::fs::metadata(&log_path).unwrap().len();
        assert!(size_after_first > 0);

        // Delete the file
        std::fs::remove_file(&log_path).unwrap();
        assert!(!log_path.exists());

        // Write again — file should be recreated
        write_to_log_with_rotation_check(path_str, &test_entry(), &config).unwrap();
        assert!(log_path.exists());
        let size_after_recreate = std::fs::metadata(&log_path).unwrap().len();
        assert!(size_after_recreate > 0);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn direct_write_recreates_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_direct_delete");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        // Write and delete
        write_to_log(path_str, &test_entry()).unwrap();
        std::fs::remove_file(&log_path).unwrap();

        // Direct write should recreate
        write_to_log(path_str, &test_entry()).unwrap();
        assert!(log_path.exists());

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn recreates_log_directory_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_dir_delete");
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        // Write, then delete entire directory
        std::fs::create_dir_all(&dir).unwrap();
        write_to_log(path_str, &test_entry()).unwrap();
        std::fs::remove_dir_all(&dir).unwrap();
        assert!(!dir.exists());

        // Write should recreate the directory and file
        write_to_log(path_str, &test_entry()).unwrap();
        assert!(dir.exists());
        assert!(log_path.exists());

        let _ = std::fs::remove_dir_all(&dir);
    }
}

use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::Path;
use std::time::Duration;

use chrono::Utc;
use flate2::write::GzEncoder;
use flate2::Compression;
use log::{info, warn};
use serde::{Deserialize, Serialize};

use crate::config::Config;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UploadConfig {
    pub upload_enabled: bool,
    pub upload_endpoint: String,
    pub upload_threshold_bytes: usize,
    pub upload_max_retries: u32,
}

impl Default for UploadConfig {
    fn default() -> Self {
        Self {
            upload_enabled: true,
            upload_endpoint: String::new(),
            upload_threshold_bytes: 524288,
            upload_max_retries: 3,
        }
    }
}

impl From<&Config> for UploadConfig {
    fn from(config: &Config) -> Self {
        Self {
            upload_enabled: config.upload_enabled,
            upload_endpoint: config.upload_endpoint.clone(),
            upload_threshold_bytes: config.upload_threshold_bytes,
            upload_max_retries: config.upload_max_retries,
        }
    }
}

#[derive(Debug, Serialize)]
struct UploadPayload {
    filename: String,
    size_bytes: u64,
    compressed_size_bytes: u64,
    timestamp: String,
    encoding: String,
    metadata: SystemMetadata,
    data: String,
}

#[derive(Debug, Serialize)]
pub struct SystemMetadata {
    pub hostname: String,
    pub username: String,
    pub home_directory: String,
}

pub fn get_system_metadata() -> SystemMetadata {
    let hostname = hostname::get()
        .map(|h| h.to_string_lossy().to_string())
        .unwrap_or_else(|_| "unknown".to_string());

    let username = std::env::var("USER")
        .or_else(|_| std::env::var("LOGNAME"))
        .unwrap_or_else(|_| "unknown".to_string());

    let home_directory = dirs::home_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|| "unknown".to_string());

    SystemMetadata {
        hostname,
        username,
        home_directory,
    }
}

fn generate_upload_filename(metadata: &SystemMetadata) -> String {
    let timestamp = Utc::now().format("%Y-%m-%d_%H-%M-%S").to_string();
    let pid = std::process::id();
    let home_basename = Path::new(&metadata.home_directory)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "unknown".to_string());

    format!(
        "{}_{}_{}_{}_{}.log",
        metadata.hostname, metadata.username, home_basename, timestamp, pid
    )
}

fn gzip_compress(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    encoder
        .write_all(data)
        .map_err(|e| format!("Gzip write failed: {}", e))?;
    encoder
        .finish()
        .map_err(|e| format!("Gzip finish failed: {}", e))
}

pub fn upload_log_file(log_file_path: &str, endpoint: &str, max_retries: u32) -> Result<(), String> {
    if endpoint.is_empty() {
        info!("Upload endpoint is empty, skipping upload");
        return Ok(());
    }

    let log_content =
        fs::read_to_string(log_file_path).map_err(|e| format!("Failed to read log file: {}", e))?;

    let size_bytes = log_content.len() as u64;
    let compressed = gzip_compress(log_content.as_bytes())?;
    let compressed_size_bytes = compressed.len() as u64;
    let metadata = get_system_metadata();
    let filename = generate_upload_filename(&metadata);

    info!(
        "Compressed log: {} -> {} bytes ({:.1}% reduction)",
        size_bytes,
        compressed_size_bytes,
        (1.0 - compressed_size_bytes as f64 / size_bytes as f64) * 100.0
    );

    let payload = UploadPayload {
        filename,
        size_bytes,
        compressed_size_bytes,
        timestamp: Utc::now().to_rfc3339(),
        encoding: "gzip+base64".to_string(),
        metadata,
        data: base64_encode(&compressed),
    };

    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .map_err(|e| format!("Failed to create HTTP client: {}", e))?;

    let mut last_err = String::new();
    for attempt in 0..=max_retries {
        if attempt > 0 {
            let backoff_ms = 1000 * 2u64.pow(attempt - 1);
            info!("Retry attempt {}/{} after {}ms", attempt, max_retries, backoff_ms);
            std::thread::sleep(Duration::from_millis(backoff_ms));
        }

        let response = client
            .post(endpoint)
            .header("Content-Type", "application/json")
            .header("Content-Encoding", "gzip")
            .header("X-Log-Size-Bytes", size_bytes.to_string())
            .json(&payload)
            .send();

        match response {
            Ok(resp) => {
                if resp.status().is_success() {
                    info!("Log file uploaded successfully to {}", endpoint);
                    return Ok(());
                }
                let status = resp.status();
                let body = resp
                    .text()
                    .unwrap_or_else(|_| "unknown error".to_string());

                // Don't retry client errors (4xx) — they won't succeed
                if status.is_client_error() {
                    warn!("Upload rejected with {}: {}", status, body);
                    return Ok(());
                }

                last_err = format!("HTTP {}: {}", status, body);
                warn!("Upload failed (attempt {}): {}", attempt + 1, last_err);
            }
            Err(e) => {
                last_err = format!("Request error: {}", e);
                warn!("Upload failed (attempt {}): {}", attempt + 1, last_err);
            }
        }
    }

    warn!("Upload exhausted {} retries: {}", max_retries, last_err);
    Ok(())
}

pub fn rotate_and_upload(log_file_path: &str, endpoint: &str, max_retries: u32) -> Result<(), String> {
    if !Path::new(log_file_path).exists() {
        return Err("Log file does not exist".to_string());
    }

    let pid = std::process::id();
    let timestamp = Utc::now().format("%Y%m%d_%H%M%S_%3f").to_string();
    let temp_copy = format!("{}.{}.{}.tmp", log_file_path, timestamp, pid);

    fs::copy(log_file_path, &temp_copy).map_err(|e| format!("Failed to copy log file: {}", e))?;
    info!("Log file copied to {}", temp_copy);

    // Upload first — only truncate on success
    let upload_result = upload_log_file(&temp_copy, endpoint, max_retries);

    match upload_result {
        Ok(_) => {
            // Upload succeeded — truncate original and delete copy
            if let Err(e) = truncate_file(log_file_path) {
                warn!("Failed to truncate log file: {}", e);
            }
            if let Err(e) = fs::remove_file(&temp_copy) {
                warn!("Failed to remove temporary copy {}: {}", temp_copy, e);
            }
            info!("Log rotated successfully");
        }
        Err(ref e) => {
            // Upload failed — keep original intact, clean up copy
            warn!("Upload failed, keeping logs intact: {}", e);
            if let Err(e) = fs::remove_file(&temp_copy) {
                warn!("Failed to remove temporary copy {}: {}", temp_copy, e);
            }
        }
    }

    upload_result
}

fn truncate_file(path: &str) -> Result<(), String> {
    let file = OpenOptions::new()
        .write(true)
        .truncate(true)
        .open(path)
        .map_err(|e| format!("Failed to truncate log file: {}", e))?;
    file.set_len(0)
        .map_err(|e| format!("Failed to set log file length to 0: {}", e))?;
    Ok(())
}

fn base64_encode(input: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::with_capacity((input.len() + 2) / 3 * 4);

    for chunk in input.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };

        let triple = (b0 << 16) | (b1 << 8) | b2;

        result.push(CHARS[((triple >> 18) & 0x3F) as usize] as char);
        result.push(CHARS[((triple >> 12) & 0x3F) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(triple & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
    }

    result
}

#[allow(dead_code)]
pub fn base64_decode(input: &str) -> Result<Vec<u8>, String> {
    let input = input.trim();
    if input.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::with_capacity(input.len() * 3 / 4);
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;

    for &byte in input.as_bytes() {
        let val = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            b' ' | b'\n' | b'\r' | b'\t' => continue,
            _ => return Err(format!("Invalid base64 character: {}", byte as char)),
        };

        buf = (buf << 6) | val as u32;
        bits += 6;

        if bits >= 8 {
            bits -= 8;
            result.push((buf >> bits) as u8);
            buf &= (1 << bits) - 1;
        }
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_config_has_expected_values() {
        let config = UploadConfig::default();
        assert!(config.upload_enabled);
        assert!(config.upload_endpoint.is_empty());
        assert_eq!(config.upload_threshold_bytes, 524288);
        assert_eq!(config.upload_max_retries, 3);
    }

    #[test]
    fn upload_config_derives_from_config() {
        let config = Config {
            upload_enabled: false,
            upload_endpoint: "http://example.com".to_string(),
            upload_threshold_bytes: 1024,
            upload_max_retries: 5,
            ..Default::default()
        };
        let upload_config = UploadConfig::from(&config);
        assert!(!upload_config.upload_enabled);
        assert_eq!(upload_config.upload_endpoint, "http://example.com");
        assert_eq!(upload_config.upload_threshold_bytes, 1024);
        assert_eq!(upload_config.upload_max_retries, 5);
    }

    #[test]
    fn base64_encoding_works() {
        assert_eq!(base64_encode(b""), "");
        assert_eq!(base64_encode(b"f"), "Zg==");
        assert_eq!(base64_encode(b"fo"), "Zm8=");
        assert_eq!(base64_encode(b"foo"), "Zm9v");
        assert_eq!(base64_encode(b"foob"), "Zm9vYg==");
        assert_eq!(base64_encode(b"fooba"), "Zm9vYmE=");
        assert_eq!(base64_encode(b"foobar"), "Zm9vYmFy");
    }

    #[test]
    fn base64_decode_roundtrip() {
        let inputs: &[&[u8]] = &[b"", b"f", b"fo", b"foo", b"foob", b"fooba", b"foobar"];
        for input in inputs {
            let encoded = base64_encode(input);
            let decoded = base64_decode(&encoded).unwrap();
            assert_eq!(decoded, *input, "roundtrip failed for {:?}", String::from_utf8_lossy(input));
        }
    }

    #[test]
    fn gzip_compress_produces_smaller_output() {
        // Repetitive data compresses well
        let data = "hello world\n".repeat(1000);
        let compressed = gzip_compress(data.as_bytes()).unwrap();
        assert!(compressed.len() < data.len(), "compressed should be smaller");
        // Gzip magic bytes
        assert_eq!(compressed[0], 0x1f);
        assert_eq!(compressed[1], 0x8b);
    }

    #[test]
    fn system_metadata_is_populated() {
        let metadata = get_system_metadata();
        assert!(!metadata.hostname.is_empty());
        assert!(!metadata.username.is_empty());
        assert!(!metadata.home_directory.is_empty());
    }

    #[test]
    fn upload_filename_includes_pid() {
        let metadata = SystemMetadata {
            hostname: "Test-MacBook".to_string(),
            username: "testuser".to_string(),
            home_directory: "/Users/testuser".to_string(),
        };

        let filename = generate_upload_filename(&metadata);
        assert!(filename.starts_with("Test-MacBook_testuser_testuser_"));
        assert!(filename.ends_with(".log"));
        let parts: Vec<&str> = filename.split('_').collect();
        assert!(parts.len() >= 5, "Expected at least 5 segments in filename");
    }

    #[test]
    fn rotate_and_upload_handles_missing_file() {
        let result = rotate_and_upload("/nonexistent/file.log", "", 3);
        assert!(result.is_err());
    }

    #[test]
    fn rotate_and_upload_skips_upload_with_empty_endpoint() {
        let dir = std::env::temp_dir().join("upload_test_rotate");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        std::fs::write(&log_path, b"test log content").unwrap();

        let result = rotate_and_upload(log_path.to_str().unwrap(), "", 3);
        assert!(result.is_ok());

        let size = std::fs::metadata(&log_path).unwrap().len();
        assert_eq!(size, 0, "Log file should be truncated after rotation");

        let _ = std::fs::remove_dir_all(&dir);
    }
}

use crate::app_paths::{config_file_path, logs_dir};
use log::{info, warn};
use serde::{Deserialize, Serialize};
use std::fs;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub device_id: String,
    pub log_dir: String,
    pub log_file: String,
    pub sample_rate_ms: u64,
    pub max_log_files: usize,
    #[serde(default)]
    pub device_id_explicit: bool,
    #[serde(default = "default_upload_enabled")]
    pub upload_enabled: bool,
    #[serde(default)]
    pub upload_endpoint: String,
    #[serde(default = "default_upload_threshold_bytes")]
    pub upload_threshold_bytes: usize,
    #[serde(default = "default_upload_max_retries")]
    pub upload_max_retries: u32,
}

fn default_upload_enabled() -> bool {
    true
}

fn default_upload_threshold_bytes() -> usize {
    524288
}

fn default_upload_max_retries() -> u32 {
    3
}

impl Default for Config {
    fn default() -> Self {
        Self {
            device_id: "0".to_string(),
            log_dir: logs_dir().display().to_string(),
            log_file: "app.log".to_string(),
            sample_rate_ms: 10,
            max_log_files: 10,
            device_id_explicit: false,
            upload_enabled: true,
            upload_endpoint: String::new(),
            upload_threshold_bytes: 524288,
            upload_max_retries: 3,
        }
    }
}

const MIN_UPLOAD_THRESHOLD_BYTES: usize = 1024;
const MAX_UPLOAD_THRESHOLD_BYTES: usize = 104857600;

impl Config {
    pub fn load() -> Self {
        let mut config = Self::load_from_file();

        // DEVICE_ID env var overrides just the device selection, preserving other settings
        if let Ok(device_id) = std::env::var("DEVICE_ID") {
            info!("Loaded DEVICE_ID from environment: {}", device_id);
            config.device_id = device_id;
            config.device_id_explicit = true;
        }

        config.validate();
        config
    }

    fn load_from_file() -> Self {
        // Try to load from the app support config file first
        let app_config_path = config_file_path();
        if let Ok(contents) = fs::read_to_string(&app_config_path) {
            if !contents.trim().is_empty() {
                match Self::from_json(&contents) {
                    Ok(config) => {
                        info!("Loaded config from {}", app_config_path.display());
                        return config;
                    }
                    Err(e) => warn!(
                        "Failed to parse config from {}: {}. Using defaults.",
                        app_config_path.display(),
                        e
                    ),
                }
            }
        }

        // Fall back to the repo-local config file for development workflows
        if let Ok(contents) = fs::read_to_string("config.json") {
            if !contents.trim().is_empty() {
                match Self::from_json(&contents) {
                    Ok(config) => {
                        info!("Loaded config from local config.json");
                        return config;
                    }
                    Err(e) => warn!("Failed to parse config.json: {}. Using defaults.", e),
                }
            }
        }

        info!("Using default configuration");
        Self::default()
    }

    fn validate(&mut self) {
        if self.upload_threshold_bytes < MIN_UPLOAD_THRESHOLD_BYTES {
            warn!(
                "upload_threshold_bytes {} is too small, clamping to {}",
                self.upload_threshold_bytes, MIN_UPLOAD_THRESHOLD_BYTES
            );
            self.upload_threshold_bytes = MIN_UPLOAD_THRESHOLD_BYTES;
        }
        if self.upload_threshold_bytes > MAX_UPLOAD_THRESHOLD_BYTES {
            warn!(
                "upload_threshold_bytes {} is too large, clamping to {}",
                self.upload_threshold_bytes, MAX_UPLOAD_THRESHOLD_BYTES
            );
            self.upload_threshold_bytes = MAX_UPLOAD_THRESHOLD_BYTES;
        }
    }

    fn from_json(contents: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(contents)
    }
}

