use std::env;
use std::fs::{self, OpenOptions};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

use chrono::Utc;
use flate2::read::GzDecoder;
use serde::Deserialize;
use tiny_http::{Header, Method, Response, Server, StatusCode};

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();

    let listen_addr = args
        .iter()
        .position(|a| a == "--listen" || a == "-l")
        .and_then(|i| args.get(i + 1))
        .unwrap_or(&"0.0.0.0:8080".to_string())
        .clone();

    let storage_dir = args
        .iter()
        .position(|a| a == "--dir" || a == "-d")
        .and_then(|i| args.get(i + 1))
        .unwrap_or(&"./received_logs".to_string())
        .clone();

    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_usage();
        return ExitCode::SUCCESS;
    }

    if let Err(e) = fs::create_dir_all(&storage_dir) {
        eprintln!("Failed to create storage dir {}: {}", storage_dir, e);
        return ExitCode::FAILURE;
    }

    let server = match Server::http(&listen_addr) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Failed to bind {}: {}", listen_addr, e);
            return ExitCode::FAILURE;
        }
    };

    println!("log-server listening on {}", listen_addr);
    println!("storing logs in {}", storage_dir);
    println!("POST /upload to submit logs");

    for request in server.incoming_requests() {
        let method = request.method().clone();
        let url = request.url().to_string();

        match (method, url.as_str()) {
            (Method::Post, "/upload") => {
                let response = handle_upload(request, &storage_dir);
                // Response already sent inside handle_upload
                let _ = response;
            }
            (Method::Get, "/health") => {
                let response = Response::from_string("{\"status\":\"ok\"}")
                    .with_header(
                        Header::from_bytes("Content-Type", "application/json").unwrap(),
                    );
                let _ = request.respond(response);
            }
            _ => {
                let response = Response::from_string("Not Found")
                    .with_status_code(StatusCode::from(404));
                let _ = request.respond(response);
            }
        }
    }

    ExitCode::SUCCESS
}

fn print_usage() {
    println!("Usage: log-server [OPTIONS]");
    println!();
    println!("Options:");
    println!("  -l, --listen <addr>   Listen address (default: 0.0.0.0:8080)");
    println!("  -d, --dir <path>      Storage directory (default: ./received_logs)");
    println!("  -h, --help            Show this help");
    println!();
    println!("Endpoints:");
    println!("  POST /upload   Upload a log file (JSON body)");
    println!("  GET  /health   Health check");
}

#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct UploadPayload {
    filename: String,
    size_bytes: u64,
    compressed_size_bytes: Option<u64>,
    timestamp: String,
    encoding: Option<String>,
    metadata: Option<Metadata>,
    data: String,
}

#[derive(Debug, Deserialize)]
struct Metadata {
    hostname: Option<String>,
    username: Option<String>,
}

fn handle_upload(mut request: tiny_http::Request, storage_dir: &str) {
    let content_type = request
        .headers()
        .iter()
        .find(|h| h.field.to_string().eq_ignore_ascii_case("content-type"))
        .map(|h| h.value.to_string())
        .unwrap_or_default();

    if !content_type.contains("application/json") {
        let _ = request.respond(json_error(400, "Content-Type must be application/json"));
        return;
    }

    // Read body
    let mut body = String::new();
    if let Err(e) = request.as_reader().read_to_string(&mut body) {
        let _ = request.respond(json_error(400, &format!("Failed to read body: {}", e)));
        return;
    }

    let payload: UploadPayload = match serde_json::from_str(&body) {
        Ok(p) => p,
        Err(e) => {
            let _ = request.respond(json_error(400, &format!("Invalid JSON: {}", e)));
            return;
        }
    };

    // Decode base64
    let raw_bytes = match base64_decode(&payload.data) {
        Ok(b) => b,
        Err(e) => {
            let _ = request.respond(json_error(400, &format!("Invalid base64: {}", e)));
            return;
        }
    };

    // Decompress if gzip
    let log_bytes = match payload.encoding.as_deref() {
        Some("gzip+base64") => match gzip_decompress(&raw_bytes) {
            Ok(d) => d,
            Err(e) => {
                let _ = request.respond(json_error(400, &format!("Gzip decompress failed: {}", e)));
                return;
            }
        },
        _ => raw_bytes,
    };

    // Build date-partitioned path
    let date_dir = Utc::now().format("%Y-%m-%d").to_string();
    let dir_path = PathBuf::from(storage_dir).join(&date_dir);
    if let Err(e) = fs::create_dir_all(&dir_path) {
        let _ = request.respond(json_error(500, &format!("Failed to create date dir: {}", e)));
        return;
    }

    // Sanitize filename
    let safe_filename = sanitize_filename(&payload.filename);
    let file_path = dir_path.join(&safe_filename);

    // Write file (handle collision)
    let written_path = match OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&file_path)
    {
        Ok(mut f) => {
            if let Err(e) = f.write_all(&log_bytes) {
                let _ = request.respond(json_error(500, &format!("Failed to write file: {}", e)));
                return;
            }
            file_path.clone()
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            let alt_name = format!(
                "{}_{}",
                Utc::now().format("%H%M%S%.3f"),
                safe_filename
            );
            let alt_path = dir_path.join(&alt_name);
            match OpenOptions::new()
                .create_new(true)
                .write(true)
                .open(&alt_path)
            {
                Ok(mut f) => {
                    if let Err(e) = f.write_all(&log_bytes) {
                        let _ = request.respond(json_error(500, &format!("Failed to write file: {}", e)));
                        return;
                    }
                    alt_path
                }
                Err(e) => {
                    let _ = request.respond(json_error(500, &format!("Failed to create file: {}", e)));
                    return;
                }
            }
        }
        Err(e) => {
            let _ = request.respond(json_error(500, &format!("Failed to create file: {}", e)));
            return;
        }
    };

    let host = payload
        .metadata
        .as_ref()
        .and_then(|m| m.hostname.as_deref())
        .unwrap_or("unknown");
    let user = payload
        .metadata
        .as_ref()
        .and_then(|m| m.username.as_deref())
        .unwrap_or("unknown");

    println!(
        "[{}] Received {} bytes from {}@{} -> {}",
        Utc::now().format("%Y-%m-%d %H:%M:%S"),
        log_bytes.len(),
        user,
        host,
        written_path.display()
    );

    let response_body = format!(
        "{{\"status\":\"received\",\"filename\":\"{}\",\"size_bytes\":{}}}",
        safe_filename,
        log_bytes.len()
    );

    let _ = request.respond(
        Response::from_string(response_body)
            .with_header(Header::from_bytes("Content-Type", "application/json").unwrap())
            .with_status_code(StatusCode::from(201)),
    );
}

fn sanitize_filename(name: &str) -> String {
    name.chars()
        .map(|c| match c {
            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => '_',
            c if c.is_control() => '_',
            c => c,
        })
        .collect()
}

fn gzip_decompress(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut decoder = GzDecoder::new(data);
    let mut decompressed = Vec::new();
    decoder
        .read_to_end(&mut decompressed)
        .map_err(|e| format!("Gzip decode error: {}", e))?;
    Ok(decompressed)
}

fn base64_decode(input: &str) -> Result<Vec<u8>, String> {
    let input = input.trim();
    if input.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::with_capacity(input.len() * 3 / 4);
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;

    for &byte in input.as_bytes() {
        let val = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            b' ' | b'\n' | b'\r' | b'\t' => continue,
            _ => return Err(format!("Invalid base64 character: {}", byte as char)),
        };

        buf = (buf << 6) | val as u32;
        bits += 6;

        if bits >= 8 {
            bits -= 8;
            result.push((buf >> bits) as u8);
            buf &= (1 << bits) - 1;
        }
    }

    Ok(result)
}

fn json_error(code: u16, msg: &str) -> Response<std::io::Cursor<Vec<u8>>> {
    let body = format!("{{\"error\":\"{}\"}}", msg.replace('"', "\\\""));
    Response::from_string(body)
        .with_header(Header::from_bytes("Content-Type", "application/json").unwrap())
        .with_status_code(StatusCode::from(code))
}

