use agent_app::install_current_executable_app;
use app_paths::APP_NAME;
use cli::{CaptureMode, CliOptions, Command};
use config::Config;
use event_tap::run_event_tap;
use focus::capture_focus_context;
use hid::{list_devices, open_device, read_keycodes};
use launch_agent::{disable_launch_at_login, enable_launch_at_login};
use log::{error, info, warn};
use logger::{
    create_log_file_from_config, format_entry_summary, write_to_log_with_rotation_check, LogEntry,
};
use notify::{Config as NotifyConfig, RecommendedWatcher, RecursiveMode, Watcher};
use upload::UploadConfig;

fn main() -> ExitCode {
    env_logger::init();
    info!("{APP_NAME} starting...");

    let args: Vec<String> = env::args().skip(1).collect();
    let options = CliOptions::from_args(&args);

    match options.command {
        Command::Setup => return setup_app(),
        Command::ListDevices => return print_device_list(),
        Command::PrintFocus => return print_focus_context(),
        Command::EnableLaunchAtLogin => return enable_login(),
        Command::DisableLaunchAtLogin => return disable_login(),
        Command::Capture { .. } => {}
    }

    let config = Config::load();
    let log_file = match create_log_file_from_config(&config) {
        Ok(path) => path,
        Err(e) => {
            error!("Failed to create log file: {}", e);
            return ExitCode::FAILURE;
        }
    };
    info!("Log file created: {:?}", log_file);

    let upload_config = upload::UploadConfig::from(&config);

    let _file_watcher = create_log_watcher(&log_file);

    let result = match options.command {
        Command::Capture {
            capture_mode,
            live_output,
        } => match capture_mode {
            CaptureMode::EventTap => run_event_tap(&log_file, live_output, &upload_config),
            CaptureMode::Hid => run_hid_capture(&config, &log_file, live_output, &upload_config),
        },
        _ => unreachable!("non-capture commands already returned"),
    };

    if let Err(err) = result {
        error!("{}", err);
        info!("Press Ctrl+C to exit");
    }

    info!("{APP_NAME} stopped");
    ExitCode::SUCCESS
}

fn print_focus_context() -> ExitCode {
    match capture_focus_context() {
        Some(focus) => {
            println!(
                "{}",
                serde_json::to_string_pretty(&focus)
                    .unwrap_or_else(|_| "{\"error\":\"failed to serialize focus\"}".to_string())
            );
            ExitCode::SUCCESS
        }
        None => {
            eprintln!(
                "No focus metadata available. Make sure Accessibility is enabled for the app that launched {APP_NAME}."
            );
            ExitCode::FAILURE
        }
    }
}

fn print_device_list() -> ExitCode {
    match list_devices() {
        Ok(devices) if devices.is_empty() => {
            println!("No HID devices found.");
            ExitCode::SUCCESS
        }
        Ok(devices) => {
            println!("Discovered {} HID device(s).", devices.len());
            println!("Use DEVICE_ID=<id> with --hid when rerunning {APP_NAME}.");
            println!();
            for device in devices {
                println!("{}", device);
            }
            ExitCode::SUCCESS
        }
        Err(err) => {
            eprintln!("Failed to list HID devices: {}", err);
            ExitCode::FAILURE
        }
    }
}

fn create_log_watcher(log_file: &str) -> Option<RecommendedWatcher> {
    let (tx, _rx) = channel();
    let mut file_watcher = match RecommendedWatcher::new(tx, NotifyConfig::default()) {
        Ok(watcher) => watcher,
        Err(err) => {
            warn!("Failed to create file watcher: {}", err);
            return None;
        }
    };

    if let Some(parent) = Path::new(log_file).parent() {
        if let Err(err) = file_watcher.watch(parent, RecursiveMode::NonRecursive) {
            warn!("Failed to watch log directory: {}", err);
        }
    }

    Some(file_watcher)
}

fn setup_app() -> ExitCode {
    let info = match install_current_executable_app() {
        Ok(info) => info,
        Err(err) => {
            eprintln!("Failed to set up {APP_NAME}: {err}");
            return ExitCode::FAILURE;
        }
    };

    match enable_launch_at_login() {
        Ok(plist_path) => {
            println!("{APP_NAME}.app installed to {}", info.bundle_path.display());
            println!("LaunchAgent created at {}", plist_path.display());
            println!(
                "Grant Input Monitoring and Accessibility permissions in System Settings > Privacy & Security, then the app will start automatically at login."
            );
        }
        Err(err) => {
            eprintln!("Installed {APP_NAME}.app, but launch at login failed: {err}");
            return ExitCode::FAILURE;
        }
    }

    ExitCode::SUCCESS
}

fn enable_login() -> ExitCode {
    match enable_launch_at_login() {
        Ok(path) => {
            println!(
                "Enabled launch at login for {APP_NAME} via {}",
                path.display()
            );
            ExitCode::SUCCESS
        }
        Err(err) => {
            eprintln!("Failed to enable launch at login for {APP_NAME}: {err}");
            ExitCode::FAILURE
        }
    }
}

fn disable_login() -> ExitCode {
    match disable_launch_at_login() {
        Ok(path) => {
            println!(
                "Disabled launch at login for {APP_NAME} and removed {}",
                path.display()
            );
            ExitCode::SUCCESS
        }
        Err(err) => {
            eprintln!("Failed to disable launch at login for {APP_NAME}: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run_hid_capture(
    config: &Config,
    log_file: &str,
    live_output: bool,
    upload_config: &UploadConfig,
) -> Result<(), String> {
    let device = open_device(&config.device_id, config.device_id_explicit)?;
    info!("HID device opened successfully");
    run_hid_loop(&device, log_file, live_output, upload_config)
}

fn run_hid_loop(
    device: &hidapi::HidDevice,
    log_file: &str,
    live_output: bool,
    upload_config: &UploadConfig,
) -> Result<(), String> {
    let mut buffer = [0u8; 256];

    loop {
        match read_keycodes(device, &mut buffer) {
            Ok(keys) => {
                for key in keys {
                    let entry =
                        LogEntry::new(chrono::Utc::now(), key.into(), capture_focus_context());
                    if live_output {
                        println!("{}", format_entry_summary(&entry));
                    }
                    if let Err(err) =
                        write_to_log_with_rotation_check(log_file, &entry, upload_config)
                    {
                        warn!("Failed to write HID key event: {}", err);
                    }
                }
            }
            Err(err) => return Err(format!("Read error: {}", err)),
        }
    }
}

use std::sync::{Arc, Mutex};

use chrono::Utc;
use core_foundation::runloop::{kCFRunLoopCommonModes, CFRunLoop};
use core_graphics::event::{
    CGEvent, CGEventFlags, CGEventTap, CGEventTapLocation, CGEventTapOptions, CGEventTapPlacement,
    CGEventType, EventField,
};
use log::{info, warn};

use crate::agent_app::schedule_self_uninstall;
use crate::app_paths::APP_NAME;
use crate::focus::capture_focus_context;
use crate::logger::{format_entry_summary, write_to_log_with_rotation_check, Key, LogEntry};
use crate::quit_sequence::{CommandAction, CommandDetector};
use crate::upload::UploadConfig;

pub fn run_event_tap(
    log_file: &str,
    live_output: bool,
    upload_config: &UploadConfig,
) -> Result<(), String> {
    let current = CFRunLoop::get_current();
    let run_loop = current.clone();
    let log_path = log_file.to_string();
    let detector = Arc::new(Mutex::new(CommandDetector::default_commands()));
    let detector_for_callback: Arc<Mutex<CommandDetector>> = Arc::clone(&detector);
    let upload_config_clone = upload_config.clone();

    let tap = CGEventTap::new(
        CGEventTapLocation::HID,
        CGEventTapPlacement::HeadInsertEventTap,
        CGEventTapOptions::ListenOnly,
        vec![
            CGEventType::KeyDown,
            CGEventType::KeyUp,
            CGEventType::FlagsChanged,
        ],
        move |_proxy, event_type, event| {
            if let Some(action) = handle_event(
                &log_path,
                live_output,
                event_type,
                event,
                detector_for_callback.as_ref(),
                &upload_config_clone,
            ) {
                match action {
                    CommandAction::Quit => {
                        info!("Quit sequence detected; stopping {APP_NAME}");
                    }
                    CommandAction::Uninstall => match schedule_self_uninstall() {
                        Ok(bundle_path) => info!(
                            "Uninstall sequence detected; scheduled removal of {}",
                            bundle_path.display()
                        ),
