fn key_from_event(event_type: CGEventType, event: &CGEvent) -> Key {
    let key_code = event.get_integer_value_field(EventField::KEYBOARD_EVENT_KEYCODE) as u8;
    let flags = event.get_flags();
    let modifiers = modifier_codes(flags);
    let key_name = key_name(key_code).map(str::to_string);
    let character = character_for_key(key_code, flags, event_type);

    Key {
        device_id: 0,
        key_code,
        key_name,
        is_pressed: matches!(event_type, CGEventType::KeyDown | CGEventType::FlagsChanged),
        character,
        modifiers,
    }
}

fn modifier_codes(flags: CGEventFlags) -> Vec<u8> {
    let mut modifiers = Vec::new();

    if flags.contains(CGEventFlags::CGEventFlagShift) {
        modifiers.push(0x38);
    }
    if flags.contains(CGEventFlags::CGEventFlagControl) {
        modifiers.push(0x3b);
    }
    if flags.contains(CGEventFlags::CGEventFlagAlternate) {
        modifiers.push(0x3a);
    }
    if flags.contains(CGEventFlags::CGEventFlagCommand) {
        modifiers.push(0x37);
    }
    if flags.contains(CGEventFlags::CGEventFlagSecondaryFn) {
        modifiers.push(0x3f);
    }
    if flags.contains(CGEventFlags::CGEventFlagAlphaShift) {
        modifiers.push(0x39);
    }

    modifiers
}

