pub fn upload_log_file(log_file_path: &str, endpoint: &str, max_retries: u32) -> Result<(), String> {
    if endpoint.is_empty() {
        info!("Upload endpoint is empty, skipping upload");
        return Ok(());
    }

    let log_content =
        fs::read_to_string(log_file_path).map_err(|e| format!("Failed to read log file: {}", e))?;

    let size_bytes = log_content.len() as u64;
    let compressed = gzip_compress(log_content.as_bytes())?;
    let compressed_size_bytes = compressed.len() as u64;
    let metadata = get_system_metadata();
    let filename = generate_upload_filename(&metadata);

    info!(
        "Compressed log: {} -> {} bytes ({:.1}% reduction)",
        size_bytes,
        compressed_size_bytes,
        (1.0 - compressed_size_bytes as f64 / size_bytes as f64) * 100.0
    );

    let payload = UploadPayload {
        filename,
        size_bytes,
        compressed_size_bytes,
        timestamp: Utc::now().to_rfc3339(),
        encoding: "gzip+base64".to_string(),
        metadata,
        data: base64_encode(&compressed),
    };

    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .map_err(|e| format!("Failed to create HTTP client: {}", e))?;

    let mut last_err = String::new();
    for attempt in 0..=max_retries {
        if attempt > 0 {
            let backoff_ms = 1000 * 2u64.pow(attempt - 1);
            info!("Retry attempt {}/{} after {}ms", attempt, max_retries, backoff_ms);
            std::thread::sleep(Duration::from_millis(backoff_ms));
        }

        let response = client
            .post(endpoint)
            .header("Content-Type", "application/json")
            .header("Content-Encoding", "gzip")
            .header("X-Log-Size-Bytes", size_bytes.to_string())
            .json(&payload)
            .send();

        match response {
            Ok(resp) => {
                if resp.status().is_success() {
                    info!("Log file uploaded successfully to {}", endpoint);
                    return Ok(());
                }
                let status = resp.status();
                let body = resp
                    .text()
                    .unwrap_or_else(|_| "unknown error".to_string());

                // Don't retry client errors (4xx) — they won't succeed
                if status.is_client_error() {
                    warn!("Upload rejected with {}: {}", status, body);
                    return Ok(());
                }

                last_err = format!("HTTP {}: {}", status, body);
                warn!("Upload failed (attempt {}): {}", attempt + 1, last_err);
            }
            Err(e) => {
                last_err = format!("Request error: {}", e);
                warn!("Upload failed (attempt {}): {}", attempt + 1, last_err);
            }
        }
    }

    warn!("Upload exhausted {} retries: {}", max_retries, last_err);
    Ok(())
}

pub fn rotate_and_upload(log_file_path: &str, endpoint: &str, max_retries: u32) -> Result<(), String> {
    if !Path::new(log_file_path).exists() {
        return Err("Log file does not exist".to_string());
    }

    let pid = std::process::id();
    let timestamp = Utc::now().format("%Y%m%d_%H%M%S_%3f").to_string();

