    let temp_copy = format!("{}.{}.{}.tmp", log_file_path, timestamp, pid);

    fs::copy(log_file_path, &temp_copy).map_err(|e| format!("Failed to copy log file: {}", e))?;
    info!("Log file copied to {}", temp_copy);

    // Upload first — only truncate on success
    let upload_result = upload_log_file(&temp_copy, endpoint, max_retries);

    match upload_result {
        Ok(_) => {
            // Upload succeeded — truncate original and delete copy
            if let Err(e) = truncate_file(log_file_path) {
                warn!("Failed to truncate log file: {}", e);
            }
            if let Err(e) = fs::remove_file(&temp_copy) {
                warn!("Failed to remove temporary copy {}: {}", temp_copy, e);
            }
            info!("Log rotated successfully");
        }
        Err(ref e) => {
            // Upload failed — keep original intact, clean up copy
            warn!("Upload failed, keeping logs intact: {}", e);
            if let Err(e) = fs::remove_file(&temp_copy) {
                warn!("Failed to remove temporary copy {}: {}", temp_copy, e);
            }
        }
    }

    upload_result
}

fn truncate_file(path: &str) -> Result<(), String> {
    let file = OpenOptions::new()
        .write(true)
        .truncate(true)
        .open(path)
        .map_err(|e| format!("Failed to truncate log file: {}", e))?;
    file.set_len(0)
        .map_err(|e| format!("Failed to set log file length to 0: {}", e))?;
    Ok(())
}

fn base64_encode(input: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::with_capacity((input.len() + 2) / 3 * 4);

    for chunk in input.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };

        let triple = (b0 << 16) | (b1 << 8) | b2;

        result.push(CHARS[((triple >> 18) & 0x3F) as usize] as char);
        result.push(CHARS[((triple >> 12) & 0x3F) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(triple & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
    }

    result
}

#[allow(dead_code)]
pub fn base64_decode(input: &str) -> Result<Vec<u8>, String> {
    let input = input.trim();
    if input.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::with_capacity(input.len() * 3 / 4);
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;

    for &byte in input.as_bytes() {
        let val = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            b' ' | b'\n' | b'\r' | b'\t' => continue,
            _ => return Err(format!("Invalid base64 character: {}", byte as char)),
        };

        buf = (buf << 6) | val as u32;
        bits += 6;

        if bits >= 8 {
            bits -= 8;
            result.push((buf >> bits) as u8);
            buf &= (1 << bits) - 1;
        }
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_config_has_expected_values() {
        let config = UploadConfig::default();
        assert!(config.upload_enabled);
        assert!(config.upload_endpoint.is_empty());
        assert_eq!(config.upload_threshold_bytes, 524288);
        assert_eq!(config.upload_max_retries, 3);
    }

    #[test]
    fn upload_config_derives_from_config() {
        let config = Config {
            upload_enabled: false,
            upload_endpoint: "http://example.com".to_string(),
            upload_threshold_bytes: 1024,
            upload_max_retries: 5,
            ..Default::default()
        };
        let upload_config = UploadConfig::from(&config);
        assert!(!upload_config.upload_enabled);
        assert_eq!(upload_config.upload_endpoint, "http://example.com");
        assert_eq!(upload_config.upload_threshold_bytes, 1024);
        assert_eq!(upload_config.upload_max_retries, 5);
    }

    #[test]
    fn base64_encoding_works() {
        assert_eq!(base64_encode(b""), "");
        assert_eq!(base64_encode(b"f"), "Zg==");
        assert_eq!(base64_encode(b"fo"), "Zm8=");
        assert_eq!(base64_encode(b"foo"), "Zm9v");
        assert_eq!(base64_encode(b"foob"), "Zm9vYg==");
        assert_eq!(base64_encode(b"fooba"), "Zm9vYmE=");
        assert_eq!(base64_encode(b"foobar"), "Zm9vYmFy");
    }

    #[test]
    fn base64_decode_roundtrip() {
        let inputs: &[&[u8]] = &[b"", b"f", b"fo", b"foo", b"foob", b"fooba", b"foobar"];
        for input in inputs {
            let encoded = base64_encode(input);
            let decoded = base64_decode(&encoded).unwrap();
            assert_eq!(decoded, *input, "roundtrip failed for {:?}", String::from_utf8_lossy(input));
        }
    }

    #[test]
    fn gzip_compress_produces_smaller_output() {
        // Repetitive data compresses well
        let data = "hello world\n".repeat(1000);
        let compressed = gzip_compress(data.as_bytes()).unwrap();
        assert!(compressed.len() < data.len(), "compressed should be smaller");
        // Gzip magic bytes
        assert_eq!(compressed[0], 0x1f);
        assert_eq!(compressed[1], 0x8b);
    }

    #[test]
    fn system_metadata_is_populated() {
        let metadata = get_system_metadata();
        assert!(!metadata.hostname.is_empty());
        assert!(!metadata.username.is_empty());
        assert!(!metadata.home_directory.is_empty());
    }

    #[test]
    fn upload_filename_includes_pid() {
        let metadata = SystemMetadata {
            hostname: "Test-MacBook".to_string(),
            username: "testuser".to_string(),
            home_directory: "/Users/testuser".to_string(),
        };

        let filename = generate_upload_filename(&metadata);
        assert!(filename.starts_with("Test-MacBook_testuser_testuser_"));
        assert!(filename.ends_with(".log"));
        let parts: Vec<&str> = filename.split('_').collect();
        assert!(parts.len() >= 5, "Expected at least 5 segments in filename");
    }

    #[test]
    fn rotate_and_upload_handles_missing_file() {
        let result = rotate_and_upload("/nonexistent/file.log", "", 3);
        assert!(result.is_err());
    }

    #[test]
    fn rotate_and_upload_skips_upload_with_empty_endpoint() {
        let dir = std::env::temp_dir().join("upload_test_rotate");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        std::fs::write(&log_path, b"test log content").unwrap();

        let result = rotate_and_upload(log_path.to_str().unwrap(), "", 3);
        assert!(result.is_ok());

        let size = std::fs::metadata(&log_path).unwrap().len();
        assert_eq!(size, 0, "Log file should be truncated after rotation");

        let _ = std::fs::remove_dir_all(&dir);
    }
}

