pub fn check_and_rotate_log(log_file: &str, upload_config: &UploadConfig) -> Result<(), String> {
    if !upload_config.upload_enabled {
        return Ok(());
    }

    // Use compare-and-swap to atomically check and set rotation flag
    let mut current = ROTATION_IN_PROGRESS.load(Ordering::SeqCst);
    while current != 0 {
        // Rotation already in progress, skip
        return Ok(());
    }

    // Try to acquire the rotation lock
    if ROTATION_IN_PROGRESS
        .compare_exchange_weak(current, 1, Ordering::SeqCst, Ordering::SeqCst)
        .is_err()
    {
        // Another thread acquired the lock
        return Ok(());
    }

    let size = match get_log_file_size(log_file) {
        Ok(size) => size,
        Err(_) => {
            // File was deleted externally — next write will recreate it
            ROTATION_IN_PROGRESS.store(0, Ordering::SeqCst);
            return Ok(());
        }
    };

    if size < upload_config.upload_threshold_bytes as u64 {
        ROTATION_IN_PROGRESS.store(0, Ordering::SeqCst);
        return Ok(());
    }

    info!(
        "Log file size {} bytes exceeds threshold {} bytes, rotating",
        size, upload_config.upload_threshold_bytes
    );

    // Rotation flag already set to 1, spawn background thread
    let log_file_owned = log_file.to_string();
    let endpoint = if upload_config.upload_endpoint.is_empty() {
        String::new()
    } else {
        upload_config.upload_endpoint.clone()
    };
    let max_retries = upload_config.upload_max_retries;

    thread::spawn(move || {
        // Ensure flag is cleared even if thread panics
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            rotate_and_upload(&log_file_owned, &endpoint, max_retries)
        }));

        match result {
            Ok(Ok(_)) => info!("Log rotation completed"),
            Ok(Err(e)) => warn!("Log rotation failed: {}", e),
            Err(_) => warn!("Log rotation thread panicked"),
        }

        // Always clear the rotation flag
        ROTATION_IN_PROGRESS.store(0, Ordering::SeqCst);
    });

    Ok(())
}

